import React from 'react';
import { debounce } from 'lodash';

const TweetCard = ({ tweet, onDelete }) => {
  const handleClick = debounce(() => {
    window.open(tweet.profileLink, '_blank');
  }, 300);

  const handleDeleteClick = () => {
    if (onDelete && typeof onDelete === 'function') {
      onDelete(tweet.id);
    }
  };

  return (
    <div className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition-all border border-gray-200 w-full">
      {/* Header with Profile Picture, Author Info, and Delete Button */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center">
          <img
            src={tweet.profile_pic || '/placeholder.jpg'}
            alt={tweet.author_name}
            className="w-10 h-10 rounded-full mr-3 object-cover"
            onError={(e) => (e.target.src = '/placeholder.jpg')} // Fallback for broken images
          />
          <div>
            <p className="font-semibold text-gray-800 leading-tight">{tweet.author_name}</p>
            <a
              href={tweet.profileLink}
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-500 text-sm hover:underline"
              onClick={handleClick}
            >
              @{tweet.author_name}
            </a>
          </div>
        </div>
        {/* Delete Button */}
        {onDelete && (
          <button
            onClick={handleDeleteClick}
            className="bg-red-500 text-white px-2 py-1 rounded text-sm hover:bg-red-600 transition-colors"
          >
            Delete
          </button>
        )}
      </div>

      {/* Tweet Content */}
      <p className="text-gray-700 text-base leading-relaxed mb-3 break-words">
        {tweet.content}
      </p>

      {/* Interaction Counts */}
      <div className="flex space-x-4 text-gray-500 text-sm">
        <span className="flex items-center">
          <span className="mr-1">❤️</span> {tweet.likes || 0}
        </span>
        <span className="flex items-center">
          <span className="mr-1">💬</span> {tweet.comments || 0}
        </span>
      </div>
    </div>
  );
};

export default TweetCard;
